type NotFound struct{ ID int }

func (e *NotFound) Error() string { return fmt.Sprintf("id %d not found", e.ID) }

func find(id int) error {
	var e *NotFound
	if id < 0 {
		e = &NotFound{ID: id}
	}
	return e
}

func main() {
	err := find(7)
	if err != nil {
		fmt.Println("failed:", err)
	} else {
		fmt.Println("ok")
	}
}

